#!/usr/bin/env node
/**
 * Regenerates two small generated files:
 *
 *   precache.json            every file the service worker should download
 *                            up front, so the whole site works offline
 *                            (all but the photographs under content/media/:
 *                            the service worker saves each of those the
 *                            first time it is shown, see sw.js)
 *   src/dev/widget-list.js   the names of all widgets, for the gallery at
 *                            #/dev/widgets and the smoke test
 *
 *   node tools/gen-precache.mjs
 *
 * Run it after adding or removing lessons, widgets or assets. Forgetting is
 * harmless: the site still works, but new files are only cached for offline
 * use once a visitor has opened them, and new widgets are missing from the
 * gallery.
 */
import { readdirSync, statSync, writeFileSync, readFileSync, existsSync } from 'node:fs';
import { join, dirname, relative, sep } from 'node:path';
import { fileURLToPath } from 'node:url';
import { createHash } from 'node:crypto';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');

const INCLUDE_DIRS = ['assets', 'vendor', 'src', 'content'];
const INCLUDE_FILES = ['index.html', 'manifest.webmanifest'];
const SKIP = [/\/licenses\//, /\.md$/i, /\.txt$/i, /LICENSE$/, /\/og\.png$/, /^src\/dev\//, /^src\/views\/dev\.js$/, /^content\/media\/.*\/manifest\.json$/,
  // detailed map layers are imported on demand by the world-map widget and cached when first used
  /^assets\/geo\/(world-50m|rivers)\.js$/];
// Pictures: there may be hundreds. They are cached when first shown, never on install.
// (content/media/<course>/index.js, the list of a course's pictures, is a module like any other and IS precached.)
const MEDIA = /^content\/media\/.+\.(?:jpe?g|png|webp|avif|gif)$/i;

function walk(dir, out = []) {
  for (const name of readdirSync(dir)) {
    if (name.startsWith('.')) continue;
    const full = join(dir, name);
    if (statSync(full).isDirectory()) walk(full, out);
    else out.push(relative(root, full).split(sep).join('/'));
  }
  return out;
}

const files = [...INCLUDE_FILES.filter((f) => existsSync(join(root, f)))];
for (const dir of INCLUDE_DIRS) if (existsSync(join(root, dir))) files.push(...walk(join(root, dir)));
const media = files.filter((f) => MEDIA.test(f));
const kept = files.filter((f) => !MEDIA.test(f) && !SKIP.some((re) => re.test(f))).sort();

const hash = createHash('sha256');
let bytes = 0;
for (const f of kept) {
  const buf = readFileSync(join(root, f));
  bytes += buf.length;
  hash.update(f).update(buf);
}
const version = hash.digest('hex').slice(0, 12);
writeFileSync(join(root, 'precache.json'), JSON.stringify({ version, files: ['./', ...kept] }, null, 1) + '\n');

const widgets = readdirSync(join(root, 'src/widgets'))
  .filter((f) => f.endsWith('.js') && !['index.js', 'kit.js'].includes(f))
  .map((f) => f.replace(/\.js$/, ''))
  .sort();
writeFileSync(
  join(root, 'src/dev/widget-list.js'),
  `/** GENERATED by tools/gen-precache.mjs — the widget modules in src/widgets. */\nexport const WIDGETS = ${JSON.stringify(widgets, null, 2)};\n`,
);

console.log(`precache.json: ${kept.length} files, ${(bytes / 1024 / 1024).toFixed(2)} MB, version ${version}`);
if (media.length) {
  const mediaBytes = media.reduce((t, f) => t + statSync(join(root, f)).size, 0);
  console.log(`  not precached: ${media.length} pictures under content/media (${(mediaBytes / 1024 / 1024).toFixed(2)} MB), cached when first shown`);
}
console.log(`src/dev/widget-list.js: ${widgets.length} widgets`);
